def shifted(S,t): return {(r+t[0],c+t[1]) for r,c in S}
def compatible_with_placed(j,t,places):
    cj=shifted(cells0[j],t); pj=shifted(ports0[j],t)
    for i,ti in places.items():
        ci=shifted(cells0[i],ti); pi=shifted(ports0[i],ti)
        if cj & ci or cj & pi or pj & ci:
            return False
    return True
def candidates_for(j,places):
    ps=set()
    for i,ti in places.items():
        key=(min(i,j),max(i,j))
        for d in pairD.get(key,()):
            if i<j: t=(ti[0]+d[0],ti[1]+d[1])
            else: t=(ti[0]-d[0],ti[1]-d[1])
            if t not in ps and compatible_with_placed(j,t,places): ps.add(t)
    return ps
def uncovered_coords(places):
    cnt=Counter()
    for i,ti in places.items():
        for p in ports0[i]: cnt[(p[0]+ti[0],p[1]+ti[1])] += 1
    return {p for p,n in cnt.items() if n==1}
def can_cover_uncovered(places, unplaced):
    unc=uncovered_coords(places)
    if not unc: return True
    # Each exposed coordinate needs at least one remaining piece that can place a port there without collision.
    for x in unc:
        possible=False
        for j in unplaced:
            for p in ports0[j]:
                t=(x[0]-p[0],x[1]-p[1])
                if compatible_with_placed(j,t,places):
                    possible=True; break
            if possible: break
        if not possible: return False
    return True
