        if ps: opts.append((j,ps))
    if not opts:return
    # A piece with exactly one possible location is forced; otherwise branch among all frontier choices.
    minlen=min(len(ps) for _,ps in opts)
    best=[(j,ps) for j,ps in opts if len(ps)==minlen]
    # To avoid missing configurations, must branch all eligible component choices.
    for j,ps in best:
        for t in sorted(ps):
            pl[j]=t; dfs(pl); del pl[j]
            if nodes>maxnodes:return
    # Also branch choices with more positions if minimum branches deadend? MRV node selection can lose solutions if choosing an unconnected-in-final node.
    # Therefore full all-options branches are needed.
    for j,ps in opts:
        if len(ps)==minlen: continue
        for t in sorted(ps):
            pl[j]=t; dfs(pl); del pl[j]
            if nodes>maxnodes:return
